  updated_at DateTime

  //----
  // RELATIONS
  //----
  shopping_mall_orders shopping_mall_orders[]
  shopping_mall_order_shipping shopping_mall_order_shipping[]

  @@unique([code])
  @@index([is_active])
  @@index([enabled_for_international])
}

