import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";

export async function test_api_customer_profile_update(
  connection: api.IConnection,
) {
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const firstName = RandomGenerator.name();
  const lastName = RandomGenerator.name();
  const updateBody = JSON.stringify({
    first_name: firstName,
    last_name: lastName,
  });

  const updateResponse: IShoppingMallCustomer =
    await api.functional.shoppingMall.customer.actors.customers.update(
      connection,
      {
        customerId,
        body: updateBody satisfies IShoppingMallCustomer.IUpdate,
      },
    );
  typia.assert(updateResponse);

  TestValidator.equals("customer ID matches", updateResponse.id, customerId);
  TestValidator.predicate(
    "first name updated",
    () => updateResponse.first_name === firstName,
  );
  TestValidator.predicate(
    "last name updated",
    () => updateResponse.last_name === lastName,
  );
  TestValidator.equals("status unchanged", updateResponse.status, "active");

  // Verify password_hash is null or unchanged (it could be null if customer was created without password)
  TestValidator.predicate(
    "password hash unchanged",
    () =>
      updateResponse.password_hash === null ||
      updateResponse.password_hash === "",
  );

  // Validate the response structure matches IShoppingMallCustomer
  TestValidator.predicate(
    "updated_at is date-time format",
    () =>
      updateResponse.updated_at && Date.parse(updateResponse.updated_at) > 0,
  );
  TestValidator.predicate(
    "created_at is date-time format",
    () =>
      updateResponse.created_at && Date.parse(updateResponse.created_at) > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";

export async function test_api_customer_profile_retrieval(
  connection: api.IConnection,
) {
  const customer: IShoppingMallCustomer =
    await api.functional.shoppingMall.actors.customers.create(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        first_name: RandomGenerator.name(),
        last_name: RandomGenerator.name(),
      } satisfies IShoppingMallCustomer.ICreate,
    });
  typia.assert(customer);

  const retrievedCustomer: IShoppingMallCustomer =
    await api.functional.shoppingMall.actors.customers.at(connection, {
      customerId: customer.id,
    });
  typia.assert(retrievedCustomer);

  // Verify public fields are present and correct
  TestValidator.equals(
    "customer ID matches",
    retrievedCustomer.id,
    customer.id,
  );
  TestValidator.equals(
    "customer email matches",
    retrievedCustomer.email,
    customer.email,
  );
  TestValidator.equals(
    "customer first name matches",
    retrievedCustomer.first_name,
    customer.first_name,
  );
  TestValidator.equals(
    "customer last name matches",
    retrievedCustomer.last_name,
    customer.last_name,
  );
  TestValidator.equals(
    "customer status is active",
    retrievedCustomer.status,
    "active",
  );
  TestValidator.equals(
    "created_at is ISO datetime",
    retrievedCustomer.created_at,
    customer.created_at,
  );
  TestValidator.equals(
    "updated_at is ISO datetime",
    retrievedCustomer.updated_at,
    customer.updated_at,
  );

  // Verify private fields are not exposed (should be undefined)
  TestValidator.equals(
    "password_hash is not exposed",
    retrievedCustomer.password_hash,
    undefined,
  );
  TestValidator.equals(
    "deleted_at is not exposed",
    retrievedCustomer.deleted_at,
    undefined,
  );
}

