export async function test_api_admin_registration_duplicate_email(
  connection: api.IConnection,
) {
  // Create a unique email for the first admin
  const uniqueEmail: string = typia.random<string & tags.Format<"email">>();

  // Create and register the first admin account
  const firstAdmin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: uniqueEmail,
        password: "SecurePassword123!",
        first_name: RandomGenerator.name(),
        last_name: RandomGenerator.name(),
        role: "full_admin",
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(firstAdmin);

  // Validate the first admin's response to confirm data integrity
  TestValidator.equals(
    "first admin email matches",
    firstAdmin.email,
    uniqueEmail,
  );
  TestValidator.equals(
    "first admin status is pending_verification",
    firstAdmin.status,
    "pending_verification",
  );
  TestValidator.equals(
    "first admin role is full_admin",
    firstAdmin.role,
    "full_admin",
  );
  TestValidator.predicate("created_at is a valid date-time format", () => {
    const date = new Date(firstAdmin.created_at);
    return !isNaN(date.getTime());
  });
  TestValidator.predicate("updated_at is a valid date-time format", () => {
    const date = new Date(firstAdmin.updated_at);
    return !isNaN(date.getTime());
  });

  // Attempt to create a second admin with the same email
  await TestValidator.error(
    "duplicate email registration should fail",
    async () => {
      await api.functional.auth.admin.join(connection, {
        body: {
          email: uniqueEmail, // Duplicate email
          password: "AnotherSecurePassword456!",
          first_name: RandomGenerator.name(),
          last_name: RandomGenerator.name(),
          role: "limited_admin",
        } satisfies IShoppingMallAdmin.ICreate,
      });
    },
  );
}

