  }

  // Perform all deletions in transaction in dependency order
  await MyGlobal.prisma.$transaction([
    // 1. Delete child records that reference customer through their own customer_id
    MyGlobal.prisma.shopping_mall_customer_sessions.deleteMany({
      where: { shopping_mall_customer_id: customerId },
    }),
    MyGlobal.prisma.shopping_mall_carts.deleteMany({
      where: { shopping_mall_customer_id: customerId },
    }),
    MyGlobal.prisma.shopping_mall_wishlists.deleteMany({
      where: { shopping_mall_customer_id: customerId },
    }),
    MyGlobal.prisma.shopping_mall_orders.deleteMany({
      where: { shopping_mall_customer_id: customerId },
    }),
    MyGlobal.prisma.shopping_mall_loyalty_point_transactions.deleteMany({
      where: { customer_id: customerId },
    }),
    MyGlobal.prisma.shopping_mall_loyalty_points.deleteMany({
      where: { customer_id: customerId },
    }),
    MyGlobal.prisma.shopping_mall_notification_preferences.deleteMany({
      where: { actor_id: customerId },
    }),
    MyGlobal.prisma.shopping_mall_audit_logs.deleteMany({
      where: { actor_id: customerId, actor_type: "customer" },
    }),

    // 2. Delete child records referenced through orders and reviews
    // Since customer.orders, customer.reviews, customer.wishlists, customer.carts do not exist,
    // we cannot use them. We remove these complex 'in' clauses with subqueries.
    // We rely instead on direct foreign key deletions above.
    // The parent entities will be deleted in step 3.

    // 3. Delete the parent entities
    MyGlobal.prisma.shopping_mall_reviews.deleteMany({
      where: { shopping_mall_customer_id: customerId },
    }),
    MyGlobal.prisma.shopping_mall_wishlists.deleteMany({
      where: { shopping_mall_customer_id: customerId },
    }),
    MyGlobal.prisma.shopping_mall_carts.deleteMany({
      where: { shopping_mall_customer_id: customerId },
    }),
    MyGlobal.prisma.shopping_mall_orders.deleteMany({
      where: { shopping_mall_customer_id: customerId },
    }),

    // 4. Delete the customer last
    MyGlobal.prisma.shopping_mall_customers.delete({
      where: { id: customerId },
    }),
  ]);

  // Create audit log entry before transaction completes
  await MyGlobal.prisma.shopping_mall_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      actor_id: props.admin.id,
      actor_type: "admin",
      event_type: "customer_delete",
      event_details: `Admin ${props.admin.id} permanently deleted customer ${customerId}`,
      status: "success",
      source: "api",
      ip_address: "N/A",
      user_agent: "System-Notification",
      created_at: toISOStringSafe(new Date()) as string &
        tags.Format<"date-time">,
      updated_at: toISOStringSafe(new Date()) as string &
        tags.Format<"date-time">,
    },
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function deleteShoppingMallCustomerOrdersOrderNumberItemsId(props: {
  customer: CustomerPayload;
  orderNumber: string;
  id: string & tags.Format<"uuid">;
}): Promise<IShoppingMallOrderItem> {
  // Find the order by orderNumber
  const order = await MyGlobal.prisma.shopping_mall_orders.findFirst({
    where: {
      order_number: props.orderNumber,
      shopping_mall_customer_id: props.customer.id,
      deleted_at: null,
    },
  });

  if (!order) {
    throw new HttpException("Order not found or access denied", 404);
  }

  // Verify order status allows deletion
  if (order.status !== "draft" && order.status !== "pending_payment") {
    throw new HttpException(
      "Cannot delete items from orders that are not in draft or pending_payment status",
      403,
    );
  }

  // Find the specific order item
  const item = await MyGlobal.prisma.shopping_mall_order_items.findFirst({
    where: {
      id: props.id,
      shopping_mall_order_id: order.id,
    },
  });

  if (!item) {
    throw new HttpException("Order item not found", 404);
  }

  // Start transaction to ensure financial consistency
  const result = await MyGlobal.prisma.$transaction(async (prisma) => {
    // Delete the order item
    await prisma.shopping_mall_order_items.delete({
      where: { id: props.id },
    });

    // Get remaining order items for recalculation
    const remainingItems = await prisma.shopping_mall_order_items.findMany({
      where: {
        shopping_mall_order_id: order.id,
      },
    });

    // Calculate new order totals
    const subtotal = remainingItems.reduce((sum, i) => sum + i.item_total, 0);
    const taxAmount = order.tax_amount; // Keep tax amount as is (per business rules)
    const shippingFee = order.shipping_fee; // Keep shipping fee as is (per business rules)
    const discountAmount = order.discount_amount; // Keep discount as is (per business rules)
    const totalAmount = subtotal + taxAmount + shippingFee - discountAmount;

    // Update the order with recalculated totals
    await prisma.shopping_mall_orders.update({
      where: { id: order.id },
      data: {
        subtotal,
        total_amount: totalAmount,
        updated_at: toISOStringSafe(new Date()),
      },
    });

    // Return the deleted item
    return item;
  });

  return {
    id: result.id,
    shopping_mall_order_id: result.shopping_mall_order_id,
    shopping_mall_product_variant_id:
      (result.shopping_mall_product_variant_id satisfies string | null as
        | string
        | null)!,
    quantity: result.quantity,
    unit_price: result.unit_price,
    item_total: result.item_total,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function deleteShoppingMallSellerProductsProductId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
}): Promise<void> {
  const product = await MyGlobal.prisma.shopping_mall_products.findUnique({
    where: {
      id: props.productId,
      shopping_mall_seller_id: props.seller.id,
      deleted_at: null,
    },
  });

  if (!product) {
    throw new HttpException("Product not found or access denied", 404);
  }

  if (product.status !== "draft") {
    throw new HttpException(
      "Only draft products can be permanently deleted",
      400,
    );
  }

  // Ensure no active orders reference this product
  const hasOrderItems = await MyGlobal.prisma.shopping_mall_order_items.count({
    where: {
      shopping_mall_product_variant_id: {
        in: (
          await MyGlobal.prisma.shopping_mall_product_variants.findMany({
            where: {
              shopping_mall_product_id: props.productId,
              deleted_at: null,
            },
            select: { id: true },
          })
        ).map((v) => v.id),
      },
    },
  });

  if (hasOrderItems > 0) {
    throw new HttpException(
      "Product cannot be deleted as it is referenced in active orders",
      400,
    );
  }

  // Ensure no active cart items reference this product
  const hasCartItems = await MyGlobal.prisma.shopping_mall_cart_items.count({
    where: {
      shopping_mall_product_variant_id: {
        in: (
          await MyGlobal.prisma.shopping_mall_product_variants.findMany({
            where: {
              shopping_mall_product_id: props.productId,
              deleted_at: null,
            },
            select: { id: true },
          })
        ).map((v) => v.id),
      },
    },
  });

  if (hasCartItems > 0) {
    throw new HttpException(
      "Product cannot be deleted as it is referenced in active carts",
      400,
    );
  }

  // Ensure no active wishlists reference this product
  const hasWishlistItems =
    await MyGlobal.prisma.shopping_mall_wishlist_items.count({
      where: {
        shopping_mall_product_variant_id: {
          in: (
            await MyGlobal.prisma.shopping_mall_product_variants.findMany({
              where: {
                shopping_mall_product_id: props.productId,
                deleted_at: null,
              },
              select: { id: true },
            })
          ).map((v) => v.id),
        },
      },
    });

  if (hasWishlistItems > 0) {
    throw new HttpException(
      "Product cannot be deleted as it is referenced in wishlists",
      400,
    );
  }

  // Get all variant IDs for deletion
  const variantIds = (
    await MyGlobal.prisma.shopping_mall_product_variants.findMany({
      where: { shopping_mall_product_id: props.productId, deleted_at: null },
      select: { id: true },
    })
  ).map((v) => v.id);

  // Delete in transaction ensuring atomicity
  await MyGlobal.prisma.$transaction([
    // Delete product images
    MyGlobal.prisma.shopping_mall_product_images.deleteMany({
      where: {
        OR: [
          { shopping_mall_product_id: props.productId },
          { shopping_mall_product_variant_id: { in: variantIds } },
        ],
        deleted_at: null,
      },
    }),

    // Delete product tags
    MyGlobal.prisma.shopping_mall_product_tags_products.deleteMany({
      where: { shopping_mall_product_id: props.productId },
    }),

    // Delete product categories
    MyGlobal.prisma.shopping_mall_product_categories.deleteMany({
      where: { shopping_mall_product_id: props.productId },
    }),

    // Delete product variants
    MyGlobal.prisma.shopping_mall_product_variants.deleteMany({
      where: { shopping_mall_product_id: props.productId },
    }),

    // Delete the product itself
    MyGlobal.prisma.shopping_mall_products.delete({
      where: { id: props.productId },
    }),
  ]);

  // Log audit event
  await MyGlobal.prisma.shopping_mall_audit_logs.create({
    data: {
      id: v4(),
      actor_id: props.seller.id,
      actor_type: "seller",
      event_type: "product_deleted",
      event_details: JSON.stringify({
        product_id: props.productId,
        product_title: product.title,
      }),
      status: "success",
      source: "api",
      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
    },
  });
}

