export async function getShoppingMallReviewsReviewId(props: {
  reviewId: string;
}): Promise<IShoppingMallReview> {
  const review = await MyGlobal.prisma.shopping_mall_reviews.findUnique({
    where: { id: props.reviewId },
  });

  if (!review) {
    throw new HttpException("Review not found", 404);
  }

  // Map Prisma status values to DTO status enum values
  const mappedStatus: IShoppingMallReview["status"] = (() => {
    switch (review.status) {
      case "published":
        return "approved";
      case "hidden":
        return "flagged";
      default:
        return review.status as IShoppingMallReview["status"];
    }
  })();

  return {
    id: review.id,
    title:
      review.title !== null && review.title !== undefined
        ? (review.title satisfies string as string)
        : "",
    body:
      review.body !== null && review.body !== undefined
        ? (review.body satisfies string as string)
        : "",
    rating: review.rating,
    status: mappedStatus,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IPageIShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSeller";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingMallAdminActorsSellers(props: {
  admin: AdminPayload;
  body: IShoppingMallSeller.IRequest;
}): Promise<IPageIShoppingMallSeller> {
  const {
    business_name,
    status,
    created_at_from,
    created_at_to,
    updated_at_from,
    updated_at_to,
  } = props.body;

  // Pagination default values according to IPage contract
  const page = 1;
  const limit = 100;
  const skip = (page - 1) * limit;

  // Build where condition - only include if value is provided
  const where: any = {
    deleted_at: null,
  };

  if (business_name !== undefined) {
    where.business_name = {
      contains: business_name,
      mode: "insensitive",
    };
  }

  if (status !== undefined) {
    where.status = status;
  }

  if (created_at_from !== undefined || created_at_to !== undefined) {
    where.created_at = {};
    if (created_at_from !== undefined) {
      where.created_at.gte = created_at_from;
    }
    if (created_at_to !== undefined) {
      where.created_at.lte = created_at_to;
    }
  }

  if (updated_at_from !== undefined || updated_at_to !== undefined) {
    where.updated_at = {};
    if (updated_at_from !== undefined) {
      where.updated_at.gte = updated_at_from;
    }
    if (updated_at_to !== undefined) {
      where.updated_at.lte = updated_at_to;
    }
  }

  // Fetch paginated results
  const [sellers, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_sellers.findMany({
      where,
      skip,
      take: limit,
      orderBy: {
        created_at: "desc",
      },
    }),
