  const { alert_type, status, seller_id, alerted_at_from, alerted_at_to } =
    props.body;

  // Build complex where condition inline for type safety
  const whereCondition = {
    // Base filters
    ...(alert_type && { alert_type }),
    ...(status && { status }),
    ...(seller_id && { seller_id }),

    // Date range conditions
