      ? {
          alerted_at: {
            ...((alerted_at_from && { gte: alerted_at_from }) || {}),
            ...((alerted_at_to && { lte: alerted_at_to }) || {}),
          },
        }
      : {}),
  };

  // Pagination parameters - use defaults from standard pagination (page 1, limit 100)
  const page = 1;
  const limit = 100;
