import { IShoppingMallOrderReturn } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderReturn";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingMallCustomerOrdersOrderNumberReturns(props: {
  customer: CustomerPayload;
  orderNumber: string;
  body: IShoppingMallOrderReturn.ICreate;
}): Promise<IShoppingMallOrderReturn> {
  // Find the order by order_number
  const order = await MyGlobal.prisma.shopping_mall_orders.findFirst({
    where: {
      order_number: props.orderNumber,
      shopping_mall_customer_id: props.customer.id,
      deleted_at: null,
    },
  });

  // Validate order exists and belongs to customer
  if (!order) {
    throw new HttpException("Order not found or access denied", 404);
  }

  // Validate order is in state that allows returns (paid, delivered, completed)
  if (!["paid", "delivered", "completed"].includes(order.status)) {
    throw new HttpException(
      "Returns are not allowed for this order status",
      400,
    );
  }

  // Check if return already exists for this order
  const existingReturn =
    await MyGlobal.prisma.shopping_mall_order_returns.findFirst({
      where: {
        shopping_mall_order_id: order.id,
      },
    });

  if (existingReturn) {
    throw new HttpException("Return already requested for this order", 409);
  }

  // Create new return request with generated UUID for id
  const newReturn = await MyGlobal.prisma.shopping_mall_order_returns.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_order_id: order.id,
      return_reason: "wrong_item",
      return_details: null,
      return_status: "requested",
      refund_amount: 0,
      return_method: "mail_return",
      return_tracking_number: null,
      return_tracking_url: null,
      approved_by_admin_id: null,
      approved_at: null,
      received_at: null,
      refund_processed_at: null,
      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // Since IShoppingMallOrderReturn is defined as a string in the DTO, return the ID
  return newReturn.id;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReview";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingMallCustomerReviews(props: {
  customer: CustomerPayload;
  body: IShoppingMallReview.ICreate;
}): Promise<IShoppingMallReview> {
  // Find customer's most recent order
  const order = await MyGlobal.prisma.shopping_mall_orders.findFirst({
    where: {
      shopping_mall_customer_id: props.customer.id,
      deleted_at: null,
    },
    orderBy: {
      created_at: "desc",
    },
    include: {
      shopping_mall_order_items: {
        take: 1,
      },
    },
  });

  if (
    !order ||
    !order.shopping_mall_order_items ||
    order.shopping_mall_order_items.length === 0
  ) {
    throw new HttpException(
      "You must have purchased a product to write a review",
      403,
    );
  }

  const firstItem = order.shopping_mall_order_items[0];
  if (!firstItem) {
    throw new HttpException("Cannot determine product for review", 403);
  }

  // Extract product_id from the first order item's relation
  const productVariantId = firstItem.shopping_mall_product_variant_id;
  if (!productVariantId) {
    throw new HttpException("Cannot determine product for review", 403);
  }

  // Find the product variant to get the associated product ID
  const productVariant =
    await MyGlobal.prisma.shopping_mall_product_variants.findUnique({
      where: { id: productVariantId },
      select: { shopping_mall_product_id: true },
    });

  if (!productVariant || !productVariant.shopping_mall_product_id) {
    throw new HttpException("Cannot determine product for review", 403);
  }

  const product_id = productVariant.shopping_mall_product_id;

  // Create review
  const review = await MyGlobal.prisma.shopping_mall_reviews.create({
    data: {
      id: v4() as string & tags.Format<"uuid">, // Fixed: Added required id field with properly typed UUID
      shopping_mall_product_id: product_id,
      shopping_mall_customer_id: props.customer.id,
      title: props.body.title ?? null,
      body: props.body.body,
      rating: props.body.rating ?? 3,
      status: "pending" as "pending" | "rejected" | "approved" | "flagged", // Fixed: Type assertion for literal union type
      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
    },
  });

  return {
    id: review.id,
    title: review.title ?? "",
    body: review.body,
    rating: review.rating,
    status: review.status as "pending" | "rejected" | "approved" | "flagged", // Fixed: Type assertion for literal union type
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallReviewReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReviewReaction";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingMallCustomerReviewsReviewIdReactions(props: {
  customer: CustomerPayload;
  reviewId: string;
  body: IShoppingMallReviewReaction.ICreate;
}): Promise<IShoppingMallReviewReaction> {
  // Validate: review must exist and belong to a different customer
  const review = await MyGlobal.prisma.shopping_mall_reviews.findUnique({
    where: { id: props.reviewId },
    select: { id: true, customer: true },
  });

  if (!review) {
    throw new HttpException("Review not found", 404);
  }

  if (review.customer.id === props.customer.id) {
    throw new HttpException("Cannot react to your own review", 403);
  }

  // Check for existing reaction from this customer on this review
  const existingReaction =
    await MyGlobal.prisma.shopping_mall_review_reactions.findUnique({
      where: {
        shopping_mall_review_id_shopping_mall_customer_id: {
          shopping_mall_review_id: props.reviewId,
          shopping_mall_customer_id: props.customer.id,
        },
      },
    });

  if (existingReaction) {
    throw new HttpException("Already reacted to this review", 409);
  }

  // Create the new reaction
  const reaction = await MyGlobal.prisma.shopping_mall_review_reactions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_review_id: props.reviewId,
      shopping_mall_customer_id: props.customer.id,
      reaction_type: typia.assert<"upvote" | "downvote">(props.body),
      created_at: toISOStringSafe(new Date()) as string &
        tags.Format<"date-time">,
    },
  });

  // Return the complete reaction object as defined by IShoppingMallReviewReaction
  return {
    type: typia.assert<"upvote" | "downvote">(reaction.reaction_type),
  };
}

