import { IShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItem";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingMallCustomerCartsCartIdItems(props: {
  customer: CustomerPayload;
  cartId: string;
  body: IShoppingMallCartItem.ICreate;
}): Promise<IShoppingMallCartItem> {
  // Validate cart exists and is active
  const cart = await MyGlobal.prisma.shopping_mall_carts.findUnique({
    where: {
      id: props.cartId,
      shopping_mall_customer_id: props.customer.id,
      status: "active",
      deleted_at: null,
    },
  });

  if (!cart) {
    throw new HttpException("Cart not found or not active", 404);
  }

  // Fetch product variant to get price and inventory
  const variant =
    await MyGlobal.prisma.shopping_mall_product_variants.findUnique({
      where: {
        id: props.body.productVariantId,
        deleted_at: null,
      },
    });

  if (!variant) {
    throw new HttpException("Product variant not found", 404);
  }

  // Determine cart item status based on inventory
  const status: "active" | "out_of_stock" =
    variant.inventory_count > 0 ? "active" : "out_of_stock";

  // Create cart item with captured price and timestamp
  const createdCartItem = await MyGlobal.prisma.shopping_mall_cart_items.create(
    {
      data: {
        id: v4() as string & tags.Format<"uuid">,
        shopping_mall_cart_id: props.cartId,
        shopping_mall_product_variant_id: props.body.productVariantId,
        price: variant.price,
        quantity: 1, // Default since not provided in ICreate
        status,
        created_at: toISOStringSafe(new Date()),
        updated_at: toISOStringSafe(new Date()),
      },
    },
  );

  return {
    price: createdCartItem.price,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItem";

export async function putShoppingMallCartsCartIdItemsItemId(props: {
  cartId: string & tags.Format<"uuid">;
  itemId: string & tags.Format<"uuid">;
  body: IShoppingMallCartItem.IUpdate;
}): Promise<IShoppingMallCartItem> {
  // Fetch cart item to validate ownership and current state
  const cartItem = await MyGlobal.prisma.shopping_mall_cart_items.findUnique({
    where: { id: props.itemId },
    include: { cart: true },
  });

  if (!cartItem) {
    throw new HttpException("Cart item not found", 404);
  }

  // Verify cart exists and is active
  if (!cartItem.cart) {
    throw new HttpException("Cart not found", 404);
  }

  // Ensure cart is active (not expired or checked out)
  const now = new Date();
  if (cartItem.cart.status !== "active" || cartItem.cart.expires_at < now) {
    throw new HttpException("Cannot modify items in non-active cart", 400);
  }

  // If no quantity change requested, return current item
  if (props.body.quantity === undefined) {
    return {
      price: cartItem.price,
    };
  }

  // Validate cart belongs to authenticated user (server-side auth ensures cart owner)
  // No need to check cartId vs user ID as auth middleware ensures ownership

  // Fetch current inventory for this product variant
  const inventory =
    await MyGlobal.prisma.shopping_mall_inventory_units.findFirst({
      where: { product_variant_id: cartItem.shopping_mall_product_variant_id },
    });

  if (!inventory) {
    throw new HttpException("Product inventory not available", 404);
  }

  // Determine new status based on quantity and inventory
  let newStatus: "active" | "out_of_stock" | "removed";
  if (props.body.quantity === 0) {
    newStatus = "removed";
  } else if (props.body.quantity > inventory.quantity) {
    newStatus = "out_of_stock";
  } else {
    newStatus = "active";
  }

  // Update cart item
  const updatedCartItem = await MyGlobal.prisma.shopping_mall_cart_items.update(
    {
      where: { id: props.itemId },
      data: {
        quantity: props.body.quantity,
        status: newStatus,
        updated_at: toISOStringSafe(new Date()),
      },
    },
  );

  return {
    price: updatedCartItem.price,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function deleteShoppingMallCartsCartIdItemsItemId(props: {
  cartId: string & tags.Format<"uuid">;
  itemId: string & tags.Format<"uuid">;
}): Promise<void> {
  const cart = await MyGlobal.prisma.shopping_mall_carts.findUnique({
    where: { id: props.cartId },
  });

  if (!cart) {
    throw new HttpException("Cart not found", 404);
  }

  if (cart.status !== "active") {
    throw new HttpException("Cart is not active", 400);
  }

  if (cart.expires_at <= new Date()) {
    throw new HttpException("Cart has expired", 400);
  }

  const item = await MyGlobal.prisma.shopping_mall_cart_items.findUnique({
    where: { id: props.itemId },
  });

  if (!item || item.shopping_mall_cart_id !== props.cartId) {
    throw new HttpException("Item not found in cart", 404);
  }

  await MyGlobal.prisma.shopping_mall_cart_items.delete({
    where: { id: props.itemId },
  });
}

