@Controller("/shoppingMall/customer/wishlists/:wishlistId/items")
export class ShoppingmallCustomerWishlistsItemsController {
  /**
   * Add a new product variant to a customer's wishlist.
   *
   * This operation allows authenticated customers to save a specific product
   * variant to one of their existing wishlists for future consideration. The
   * customer must specify both the target wishlist ID and the product variant
   * ID to be added. This creates a new entry in the
   * shopping_mall_wishlist_items table that links the customer, wishlist, and
   * product variant.
   *
   * The operation validates that the specified wishlist exists and belongs to
   * the authenticated customer, and that the product variant is a valid, active
   * product in the catalog. Duplicate entries are blocked through a unique
   * constraint on the combination of wishlist_id and product_variant_id -
   * attempting to add the same product variant to the same wishlist will result
   * in a failure. No delegation or side effects occur from this operation; it
   * simply creates the relationship record.
   *
   * The request body must include the product_variant_id field for the target
   * product variant. Optional fields like note can be included to provide
   * customer context for the item. This operation is primarily used as a
   * bookmarking mechanism rather than a purchasing action. The system does not
   * reserve inventory, adjust pricing, or notify the seller upon adding an item
   * to wishlist. Customer preferences and notes are preserved as-is.
   *
   * Upon successful completion, the operation returns the complete details of
   * the newly created wishlist item with its system-generated ID and creation
   * timestamp. The operation operates on the shopping_mall_wishlist_items table
   * and references the shopping_mall_wishlists and
   * shopping_mall_product_variants tables through foreign keys. No response
   * body is included if the operation fails due to validation errors or
   * duplicate entries.
   *
   * Related operations: Retrieve single wishlist item (GET
   * /wishlists/{wishlistId}/items/{itemId}), List all items in a wishlist
   * (PATCH /wishlists/{wishlistId}/items), Remove item from wishlist (DELETE
   * /wishlists/{wishlistId}/items/{itemId}).
   *
   * @param connection
   * @param wishlistId Unique identifier of the wishlist to which the product
   *   variant should be added. This must be the ID of a wishlist owned by the
   *   authenticated customer.
   * @param body The product variant to add to the wishlist along with optional
   *   customer note.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("wishlistId")
    wishlistId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IShoppingMallWishlistItem.ICreate,
  ): Promise<IShoppingMallWishlistItem> {
    try {
      return await postShoppingMallCustomerWishlistsWishlistIdItems({
        customer,
        wishlistId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a paginated list of all items in a specific wishlist, supporting
   * search, filtering, and sorting functionality. This operation operates on
   * the shopping_mall_wishlist_items model and returns all product variants
   * associated with the specified wishlist.
   *
   * The operation first validates that the authenticated user is the owner of
   * the wishlist by comparing the user ID from the authentication token with
   * the shopping_mall_customer_id field in the corresponding
   * shopping_mall_wishlists record. If the user is not the owner, the operation
   * fails with access denied error.
   *
   * Search functionality allows users to filter items by product name,
   * description, or custom note using text matching. Filters can be applied to
   * product categories, price ranges, or availability status. Results can be
   * sorted by creation date (newest/oldest), product name (A-Z/Z-A), or price
   * (low-high/high-low).
   *
   * The response includes pagination metadata with the total count of items,
   * current page, page size, and total pages to support client-side navigation.
   * This operation does not modify any data and is read-only.
   *
   * This operation retrieves data from the shopping_mall_wishlist_items model
   * and joins with shopping_mall_product_variants to provide comprehensive
   * product information. The response uses the
   * IPageIShoppingMallWishlistItem.ISummary type for efficient data
   * transmission with optimized fields for list display.
   *
   * Note that the wishlist items are not soft-deleted - only the wishlist
   * itself can be deleted, but items can have modified status through deletion
   * (via deleted_at field).
   *
   * @param connection
   * @param wishlistId Unique identifier of the wishlist whose items are being
   *   retrieved. This is the primary key of the shopping_mall_wishlists model
   *   and establishes the parent context for all returned items.
   * @param body Search criteria, filters, and pagination parameters for
   *   retrieving wishlist items.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("wishlistId")
    wishlistId: string,
    @TypedBody()
    body: IShoppingMallWishlistItem.IRequest,
  ): Promise<IPageIShoppingMallWishlistItem.ISummary> {
    try {
      return await patchShoppingMallCustomerWishlistsWishlistIdItems({
        customer,
        wishlistId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a specific item from a customer's wishlist.
   *
   * This operation fetches detailed information about a single product variant
   * that has been saved to a specific wishlist by a customer. The item
   * information includes the product variant details and any optional
   * user-provided note. This endpoint allows customers to view individual
   * wishlist items for review or reconsideration.
   *
   * The operation requires both the wishlist ID and item ID in the path
   * parameters to uniquely identify the wishlist item. Only the owner of the
   * wishlist can access items within their wishlist. The item's product variant
   * data is returned with current pricing and availability information at the
   * time of retrieval, as product details may change since the item was added
   * to the wishlist.
   *
   * The returned data includes the product variant's name, product catalog
   * details, current price, stock status, and any custom note provided by the
   * customer. The operation operates on the shopping_mall_wishlist_items table
   * and joins with the shopping_mall_product_variants table to provide
   * comprehensive item details. No request body is required for this read
   * operation.
   *
   * Related operations: List all items in a wishlist (POST
   * /wishlists/{wishlistId}/items), Add item to wishlist (POST
   * /wishlists/{wishlistId}/items), Remove item from wishlist (DELETE
   * /wishlists/{wishlistId}/items/{itemId}).
   *
   * @param connection
   * @param wishlistId Unique identifier of the wishlist containing the target
   *   item. This must be the ID of a wishlist owned by the authenticated
   *   customer.
   * @param itemId Unique identifier of the specific wishlist item to retrieve.
   *   This identifies the individual entry in the wishlist joining the customer
   *   with a specific product variant.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":itemId")
  public async at(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("wishlistId")
    wishlistId: string & tags.Format<"uuid">,
    @TypedParam("itemId")
    itemId: string & tags.Format<"uuid">,
  ): Promise<IShoppingMallWishlistItem> {
    try {
      return await getShoppingMallCustomerWishlistsWishlistIdItemsItemId({
        customer,
        wishlistId,
        itemId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update an individual product item within a wishlist with new annotations or
   * priority.
   *
   * This operation allows a customer to modify any attribute of a specific
   * product item in their wishlist, including adding or updating a personal
   * note. The operation validates that both the wishlist and product variant
   * referenced exist, are owned by the authenticated customer, and are not
   * deleted. This action does not affect inventory or pricing, as wishlist
   * items are for interest tracking rather than purchase. If a customer removes
   * or updates a note, this change is persistent and immediately visible across
   * all their sessions. This operation is designed to support personalization
   * of wishlists without triggering any business logic related to purchasing or
   * inventory management.
   *
   * Note: This is NOT a product update - product pricing and availability
   * remain dynamic. Only metadata about the wishlist item (the customer's note)
   * can be modified. The system tracks when this update occurred for audit
   * purposes.
   *
   * Related operations: DELETE /wishlists/{wishlistId}/items/{itemId} (removes
   * item from wishlist).
   *
   * @param connection
   * @param wishlistId Unique identifier of the target wishlist. Must belong to
   *   the authenticated user.
   * @param itemId Unique identifier of the target wishlist item. Must be
   *   associated with the specified wishlist and owned by the authenticated
   *   user.
   * @param body Updated information for the wishlist item, primarily focused on
   *   the customer's personal note.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put(":itemId")
  public async update(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("wishlistId")
    wishlistId: string & tags.Format<"uuid">,
    @TypedParam("itemId")
    itemId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IShoppingMallWishlistItem.IUpdate,
  ): Promise<IShoppingMallWishlistItem> {
    try {
      return await putShoppingMallCustomerWishlistsWishlistIdItemsItemId({
        customer,
        wishlistId,
        itemId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Permanently remove an individual product item from a customer's wishlist.
   *
   * This operation allows a customer to delete a specific product item from
   * their wishlist, effectively removing their expression of interest in that
   * product. The delete operation is immediate and irreversible. After
   * deletion, the item is marked with a soft-delete timestamp (deleted_at) to
   * maintain audit trails without permanently erasing historical data. The
   * deletion does not affect inventory levels or related purchase data, as
   * wishlist items are purely for tracking interest, not transactions.
   *
   * Soft delete behavior: The item's deleted_at field is set to the current
   * timestamp, and the item is filtered out of response queries, but is not
   * physically removed from the database.
   *
   * Related operations: PUT /wishlists/{wishlistId}/items/{itemId} (updates
   * item information).
   *
   * @param connection
   * @param wishlistId Unique identifier of the target wishlist from which the
   *   item should be removed. Must belong to the authenticated user.
   * @param itemId Unique identifier of the wishlist item to be removed. Must be
   *   associated with the specified wishlist and owned by the authenticated
   *   user.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Delete(":itemId")
  public async erase(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("wishlistId")
    wishlistId: string & tags.Format<"uuid">,
    @TypedParam("itemId")
    itemId: string & tags.Format<"uuid">,
  ): Promise<void> {
    try {
      return await deleteShoppingMallCustomerWishlistsWishlistIdItemsItemId({
        customer,
        wishlistId,
        itemId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

